#include "simulation.hpp"
#include <iostream>
#include <stdexcept>
namespace life {struct NativeSimulationTestAccess {
  static std::vector<Organism>& records(NativeSimulation& s){return s.organisms_;}
  static void capture(NativeSimulation& s,Organism& o){s.captureDecision(o);}
  static void reindex(NativeSimulation& s){s.slotById_.clear();for(size_t i=0;i<s.organisms_.size();++i)s.slotById_[s.organisms_[i].id]=i;s.familyRoot_=-2;}
};}
void expect(bool valid,const char* message){if(!valid)throw std::runtime_error(message);}
int main(){try{
  life::FollowCamera a,b;a.begin(1,50,30,0,0,2,800,600);b=a;for(int i=0;i<30;++i)a.advance(50,30,true,2,800,600,1./30);for(int i=0;i<120;++i)b.advance(50,30,true,2,800,600,1./120);expect(std::abs(a.offsetX-b.offsetX)<1e-8,"Camera depends on frame rate");
  a.begin(1,1023,639,-2046,-1278,2,800,600);a.advance(0,0,true,2,800,600,.016);expect(std::abs(a.anchorX-1024)<1e-8&&std::abs(a.anchorY-640)<1e-8,"Camera took long border path");const auto frozen=a.offsetX;a.advance(300,30,true,2,800,600,1,true);expect(a.offsetX==frozen,"Atlas did not suspend camera");a.release();a.advance(300,30,true,2,800,600,1);expect(a.offsetX==frozen,"Released camera moved");a.following=true;a.advance(0,0,false,2,800,600,.1);expect(!a.following&&a.wrapped,"Dead target did not hold wrapped view");
  life::NativeSimulation observed(96,60,.2,500,524114809,334462),control(96,60,.2,500,524114809,334462);observed.seedBenchmarkMovers(150);control.seedBenchmarkMovers(150);int mover=-1;for(const auto& o:observed.organisms())if(o.isMover){mover=o.id;break;}observed.watch(mover);observed.select(mover);observed.step(400);control.step(400);expect(observed.cells==control.cells&&observed.owners==control.owners&&observed.world.nutrients==control.world.nutrients&&observed.moisture==control.moisture,"Observation changed physics");expect(observed.birthCount()==control.birthCount()&&observed.organisms().size()==control.organisms().size(),"Observation changed lifecycle");for(size_t i=0;i<observed.organisms().size();++i){const auto& x=observed.organisms()[i];const auto& y=control.organisms()[i];expect(x.energy==y.energy&&x.lastOutputs==y.lastOutputs&&x.lastFeatures==y.lastFeatures,"Observation changed neural state");}
  life::NativeSimulation family(32,32,.2,500,1,1);auto& records=life::NativeSimulationTestAccess::records(family);auto root=records.front();records.clear();root.id=10;root.parentId=-1;root.directOffspring=2;records.push_back(root);for(int id:{11,12,13}){auto child=root;child.id=id;child.parentId=id==13?11:10;child.birthTick=id==11?8:id==12?5:1;records.push_back(child);}life::NativeSimulationTestAccess::reindex(family);family.watch(10);auto snap=family.watchedSnapshot();expect(snap.livingChildren==2&&snap.livingDescendants==3&&snap.nextDescendant==12,"Family counts or oldest child wrong");expect(family.familyRoles(10).at(13)==life::FamilyRole::Descendant,"Grandchild classified as child");records[1].living=records[2].living=false;life::NativeSimulationTestAccess::reindex(family);snap=family.watchedSnapshot();expect(snap.nextDescendant==13,"Descendant fallback wrong");
  auto& watched=records.front();watched.lastAction=3;watched.lastFeatures={0,12,life::NutrientFeatureOffset};watched.lastOutputs={-2,1,0,4,-1};for(int i=0;i<150;++i)life::NativeSimulationTestAccess::capture(family,watched);snap=family.watchedSnapshot();expect(snap.decisionCount==128&&snap.hasDecision&&snap.decision.outputs==watched.lastOutputs&&snap.decision.featureCount==3,"Decision capture/history wrong");const auto decoded=life::decodeSenses(snap.decision);expect(!decoded.empty()&&decoded.front().nutrients&&(decoded.front().categories&(1u<<12)),"Sense decoder changed captured features");family.watch(13);expect(!family.watchedSnapshot().hasDecision,"New target reused old decisions");family.watch(-1);expect(family.watchedPose().id==-1,"Cleared watcher remained active");
  std::cout<<"Follow camera, family cache, exact decisions and observation replay passed\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
